arguments.query:
SELECT ?metric ?value ?scored ?eligible ?status WHERE {
  ?result rb:resultFor id:rewire-model-baseline-kmer-position-v2 ; rb:resultOn id:rewire-mfass-v2 ; rb:metric ?metric ;
          mls:hasValue ?value ; rb:status ?status .
  OPTIONAL { ?result rb:coverage ?c . ?c rb:scoredCount ?scored ; rb:eligibleCount ?eligible }
} ORDER BY ?metric
